solution.javascript:
function deuxPaquets(poids, cible) {
  const vus = new Map();
  for (let j = 0; j < poids.length; j++) {
    const i = vus.get(cible - poids[j]);
    if (i !== undefined) {
      return [i, j];
    }
    if (!vus.has(poids[j])) {
      vus.set(poids[j], j);
    }
  }
  return [];
}

