solution.javascript:
function plusLongueSerie(variations, cible) {
  // premiere.get(s) : plus petit k tel que les k premiers jours totalisent s
  const premiere = new Map();
  premiere.set(0, 0);
  let somme = 0;
  let meilleur = [];
  let longueur = 0;
  for (let k = 1; k <= variations.length; k++) {
    somme = somme + variations[k - 1];
    const debut = premiere.get(somme - cible);
    if (debut !== undefined && k - debut > longueur) {
      longueur = k - debut;
      meilleur = [debut, k - 1];
    }
    if (!premiere.has(somme)) {
      premiere.set(somme, k);
    }
  }
  return meilleur;
}

solution.python:
def plus_longue_serie(variations, cible):
    # premiere[s] : plus petit k tel que les k premiers jours totalisent s
    premiere = {0: 0}
    somme = 0
    meilleur = []
    longueur = 0
    for k in range(1, len(variations) + 1):
        somme = somme + variations[k - 1]
        debut = premiere.get(somme - cible)
        if debut is not None and k - debut > longueur:
            longueur = k - debut
            meilleur = [debut, k - 1]
        if somme not in premiere:
            premiere[somme] = k
    return meilleur

